-- Semilla de ajustes del sitio (site_settings): home, nosotros, paginas, seo.
-- GENERADO desde src/data/ajustes.ts.
--
-- `contact` NO se reescribe entera aquí: ya viene sembrada en
-- 0001_contenido.sql §6, y es el origen del número destino del formulario.
-- Volver a escribirla desde una semilla sería pisar lo que el panel haya
-- ajustado. Al final de este archivo solo se le fusionan dos cosas: el horario
-- de atención y los canales públicos de contacto, que cambiaron después de esa
-- migración. El resto de sus claves quedan como estén.
--
-- La forma de cada JSON está documentada en src/lib/content-types.ts §5.
--
-- ⚠ En `nosotros`, los cuerpos de «Misión» y «Visión» van INTERCAMBIADOS
-- respecto al documento original de PIYC, por decisión de Cesar (21-sep-2026):
-- lo que el documento rotulaba «Visión» describe lo que la empresa hace hoy y
-- lo rotulado «Misión» describe a dónde quiere llegar. Los rótulos no se
-- movieron. Ver docs/CONTENIDO.md §4.
--
-- Idempotente: `do update` deja el JSON como dice este archivo.

insert into public.site_settings (key, value)
values
  ('home', '{"cta":{"body":"Cuéntenos qué necesita y con qué restricciones trabaja su planta. Respondemos por WhatsApp y, si hace falta, vamos a verlo en sitio.","nota":{"texto":"También puede","enlace":{"href":"/servicios","etiqueta":"revisar el portafolio de servicios"},"textoFinal":"antes de escribirnos."},"title":"¿Tiene un proceso que automatizar o un tablero que rehacer?","ctaPrimario":{"href":"whatsapp","etiqueta":"Escríbanos por WhatsApp"},"ctaSecundario":{"href":"/contacto","etiqueta":"Ir al formulario de contacto"}},"hero":{"title":"Automatización industrial, tableros de control e ingeniería eléctrica en Cali","eyebrow":"Ingeniería eléctrica · Automatización · Control","subtitle":"Somos un equipo de ingenieros especializados en proyectos de ingeniería, montaje y mantenimiento de equipos eléctricos y electrónicos. Automatizamos equipos y ejecutamos obras eléctricas: desde el control de procesos hasta el desarrollo de equipos de óptima calidad.","ctaPrimario":{"href":"/servicios","etiqueta":"Ver servicios"},"ctaSecundario":{"href":"whatsapp","etiqueta":"Escríbanos por WhatsApp"}},"intro":{"body":"PIYC trabaja sobre plantas en producción: procesos que no pueden parar más de lo planeado y equipos que tienen que seguir operando cuando el proyecto termina. Por eso el trabajo empieza en el sitio —levantando lo que hay, midiendo cargas reales y entendiendo la secuencia— antes de proponer un solo equipo.\n\nCubrimos el ciclo completo: el diseño eléctrico y el P&ID, el tablero armado según ese plano, la programación del PLC y la supervisión HMI/SCADA, el montaje electromecánico y la puesta en marcha con el proceso corriendo. Al cerrar entregamos planos as-built, programas documentados y capacitación, porque un sistema que solo puede mantener quien lo instaló es un problema aplazado.","image":{"alt":"Skid de proceso en acero inoxidable con su panel de control, tuberías sanitarias y bomba, instalado en una sala de producción","src":"https://bzrjeduxjkwvtdaohjrh.supabase.co/storage/v1/object/public/site-images/inicio/skid-proceso-inoxidable-900.webp","width":900,"height":1200},"title":"Ingeniería que se queda funcionando","eyebrow":"Qué hacemos","ctaEtiqueta":"Conocer a PIYC"},"proceso":{"intro":"El orden importa: saltarse el diagnóstico se paga en el montaje, y saltarse la documentación se paga en el primer mantenimiento.","pasos":[{"titulo":"Diagnóstico","descripcion":"Visita a planta: levantamiento de lo instalado, medición de cargas reales y revisión de la secuencia del proceso con quien lo opera."},{"titulo":"Diseño","descripcion":"Unifilar, cuadro de cargas, P&ID y lista de señales. Se define el alcance, se seleccionan los equipos y se acuerda la ventana de parada."},{"titulo":"Montaje","descripcion":"Armado del tablero contra plano, canalizaciones, cableado marquillado e instalación de instrumentos y equipos de campo."},{"titulo":"Puesta en marcha","descripcion":"Pruebas punto a punto, carga del programa, ajuste de lazos de control y arranque con el proceso en operación y el operario presente."},{"titulo":"Soporte","descripcion":"Entrega de planos as-built, programas y manual, capacitación al personal y acompañamiento para afinar lo que solo se ve produciendo."}],"title":"Cinco etapas, en este orden","eyebrow":"Cómo trabajamos"},"seccionValores":{"intro":"Cuatro criterios que se notan en cómo se cotiza, cómo se ejecuta y qué se entrega al final del proyecto.","title":"Nuestros valores","eyebrow":"Lo que sostiene el trabajo"},"seccionProyectos":{"intro":"Automatizaciones y sistemas de control ejecutados en plantas de producción del Valle del Cauca.","title":"Proyectos entregados y funcionando","eyebrow":"Casos de éxito","ctaEtiqueta":"Ver todos los proyectos"},"seccionServicios":{"intro":"Nueve servicios para el ciclo completo: diseñar la instalación, armarla, ponerla a producir y sostenerla después.","title":"Servicios","eyebrow":"Portafolio","ctaEtiqueta":"Ver los nueve servicios"},"proyectosDestacados":["preparacion-alcohol-jgb","pasteurizador-alival","estacion-cargue-alival"],"serviciosDestacados":["automatizacion-procesos-industriales","tableros-de-control","diseno-ingenieria-electrica","telemetria"]}'::jsonb),
  ('nosotros', '{"cta":{"body":"Cuéntenos qué necesita su planta y con qué restricciones trabaja. Revisamos el alcance antes de proponer cualquier cosa.","title":"¿Quiere trabajar con nosotros?"},"hero":{"image":{"alt":"Cuarto eléctrico con una fila de tableros de control y fuerza montados contra la pared; uno de ellos abierto durante el cableado","src":"https://bzrjeduxjkwvtdaohjrh.supabase.co/storage/v1/object/public/site-images/cabeceras/cuarto-electrico-tableros-900.webp","width":900,"height":442},"title":"Ingenieros que trabajan dentro de la planta, no sobre el catálogo","eyebrow":"Quiénes somos","subtitle":"PROGRAMACIÓN INDUSTRIAL Y CONTROL S.A.S. —PIYC— desarrolla proyectos de ingeniería, montaje y mantenimiento de equipos eléctricos y electrónicos para la industria del Valle del Cauca."},"mision":{"body":"Proveer soluciones innovadoras en el desarrollo, el mantenimiento y el control de proyectos de ingeniería, adaptándonos a las necesidades específicas de cada cliente, con estándares de alta calidad y una cultura de mejora continua.","title":"Misión"},"vision":{"body":"Posicionarnos como el proveedor líder de servicios para el sector industrial, reafirmando nuestro profesionalismo al transformar cada idea en soluciones efectivas, con equilibrio entre las necesidades del cliente, el compromiso, los altos estándares de calidad y los resultados.","title":"Visión"},"galeria":[{"alt":"Técnico con overol y cofia trabaja en el cableado interno de un tablero de control dentro de una planta de alimentos","src":"https://bzrjeduxjkwvtdaohjrh.supabase.co/storage/v1/object/public/site-images/nosotros/tecnico-cableando-tablero.webp","width":888,"height":1920},{"alt":"Técnico con la chaqueta de PIYC interviene el cableado de un tablero de control en acero inoxidable","src":"https://bzrjeduxjkwvtdaohjrh.supabase.co/storage/v1/object/public/site-images/nosotros/tecnico-piyc-tablero-inox.webp","width":447,"height":489},{"alt":"Tablero de control abierto durante la puesta en marcha, con un portátil conectado al PLC para cargar el programa","src":"https://bzrjeduxjkwvtdaohjrh.supabase.co/storage/v1/object/public/site-images/nosotros/programacion-tablero-portatil.webp","width":934,"height":1920},{"alt":"Puesta en marcha de un tablero en acero inoxidable con tres variadores de velocidad, con el portátil y el terminal de pruebas sobre la mesa","src":"https://bzrjeduxjkwvtdaohjrh.supabase.co/storage/v1/object/public/site-images/nosotros/puesta-en-marcha-variadores.webp","width":888,"height":1920},{"alt":"Tablero con PLC modular, protecciones y borneras, con un portátil conectado durante la programación","src":"https://bzrjeduxjkwvtdaohjrh.supabase.co/storage/v1/object/public/site-images/nosotros/tablero-plc-modular-portatil.webp","width":933,"height":1920},{"alt":"Tablero de doble puerta recién armado, con contactores, fuentes y borneras ordenadas por nivel","src":"https://bzrjeduxjkwvtdaohjrh.supabase.co/storage/v1/object/public/site-images/nosotros/tablero-doble-puerta-armado-900.webp","width":900,"height":1200},{"alt":"Gabinete de fuerza abierto con seccionador, interruptores de caja moldeada y equipo de respaldo en la base","src":"https://bzrjeduxjkwvtdaohjrh.supabase.co/storage/v1/object/public/site-images/nosotros/gabinete-fuerza-armado-900.webp","width":900,"height":1660},{"alt":"Tablero en acero inoxidable con PLC compacto, switch de red y borneras; guantes dieléctricos colgados en la puerta","src":"https://bzrjeduxjkwvtdaohjrh.supabase.co/storage/v1/object/public/site-images/nosotros/tablero-inox-plc-siemens-900.webp","width":900,"height":1600},{"alt":"Tablero de fuerza abierto con barraje de cobre, interruptores automáticos y bloques de borneras","src":"https://bzrjeduxjkwvtdaohjrh.supabase.co/storage/v1/object/public/site-images/nosotros/tablero-fuerza-barraje.webp","width":933,"height":1920}],"valores":{"intro":"Cuatro criterios que se notan en cómo se cotiza, cómo se ejecuta y qué se entrega al final del proyecto.","title":"Nuestros valores","eyebrow":"Cómo trabajamos"},"quienesSomos":{"body":"Somos una empresa integrada por ingenieros altamente calificados, especializados en el desarrollo de proyectos de ingeniería, montaje y mantenimiento de equipos eléctricos y electrónicos. Nos dedicamos a la automatización de equipos, así como a la ejecución de obras eléctricas y electrónicas. Nuestro enfoque abarca desde la automatización y el control hasta el desarrollo de equipos de óptima calidad.\n\nOfrecemos servicios de alta calidad para dar soluciones asertivas, reduciendo el riesgo y dando la seguridad de que nuestra propuesta es la mejor, brindando tranquilidad y respaldo a cada cliente en su proceso de producción.","image":{"alt":"Dos técnicos con traje y cofia de planta revisan el programa en un portátil apoyado sobre el tablero, dentro de una sala de producción","src":"https://bzrjeduxjkwvtdaohjrh.supabase.co/storage/v1/object/public/site-images/nosotros/equipo-planta-alimentos-900.webp","width":900,"height":1200},"title":"Quiénes somos","eyebrow":"La empresa"},"bloqueGaleria":{"title":"Nuestro trabajo","eyebrow":"En obra"}}'::jsonb),
  ('paginas', '{"contacto":{"faq":[{"pregunta":"¿Qué pasa cuando envío el formulario?","respuesta":"Se abre WhatsApp con el mensaje ya escrito —sus datos y lo que nos contó— para que solo tenga que darle enviar. El sitio no envía correos automáticos. Si su navegador bloquea la ventana, aparece un enlace para abrirlo a mano."},{"pregunta":"¿Qué información les sirve para dar un alcance?","respuesta":"Entre más concreto, mejor: qué equipo o proceso es, qué marca y referencia de controlador tiene hoy si lo sabe, qué falla o qué quiere lograr, y si la planta puede parar o no. Con eso le decimos qué falta para cotizar."},{"pregunta":"¿Atienden fuera de Cali?","respuesta":"La base está en Cali, Valle del Cauca. Para trabajos en otras ciudades escríbanos con el alcance y lo revisamos: depende del tipo de proyecto y del tiempo de montaje en sitio."},{"pregunta":"¿Puedo escribirles directamente por WhatsApp?","respuesta":"Sí. El botón verde del sitio abre una conversación con nuestro número de WhatsApp, que también aparece en esta página. El formulario existe para que el mensaje llegue con los datos completos desde el primer envío."}],"title":"Cuéntenos qué necesita su planta","eyebrow":"Contacto","subtitle":"Escríbanos por WhatsApp o déjenos los datos del proyecto en el formulario. Respondemos con las preguntas técnicas que hagan falta antes de proponer nada.","notaFormulario":"Los datos que escriba aquí se usan únicamente para responder su solicitud. No compartimos su información con terceros ni lo suscribimos a ningún boletín.","introFormulario":"Al enviar, se abre WhatsApp con el mensaje ya escrito para que solo tenga que darle enviar. No enviamos correos automáticos."},"proyectos":{"cta":{"body":"Cuéntenos qué proceso quiere intervenir y con qué restricciones trabaja su planta.","title":"¿Tiene un proyecto parecido?"},"image":{"alt":"Vista cenital del montaje interno de un tablero: PLC, switch de red, fuente de 24 V, protecciones y borneras numeradas sobre riel","src":"https://bzrjeduxjkwvtdaohjrh.supabase.co/storage/v1/object/public/site-images/cabeceras/montaje-interno-tablero-900.webp","width":900,"height":507},"intro":"Cada caso describe la situación de partida, lo que se hizo y cómo quedó el proceso después. Las cifras que aparecen son las que midió el mismo proceso del cliente.","title":"Proyectos entregados y funcionando","eyebrow":"Casos de éxito","subtitle":"Automatizaciones, sistemas de control y proyectos de ingeniería eléctrica ejecutados en plantas de producción del Valle del Cauca."},"servicios":{"cta":{"body":"Descríbanos el problema —el proceso, el equipo o la falla— y le decimos por dónde se aborda antes de cotizar nada.","title":"¿No está seguro de qué servicio necesita?"},"faq":[{"pregunta":"¿Atienden plantas que no pueden parar la producción?","respuesta":"Sí. La ventana de parada es parte del diseño, no un detalle de última hora: se acuerda desde la etapa de ingeniería y el montaje se planea alrededor de ella, dejando para la parada solo lo que obligatoriamente va ahí."},{"pregunta":"¿Trabajan sobre equipos y PLC que ya están instalados?","respuesta":"Sí. Buena parte de los proyectos son migraciones y repotenciaciones: se conserva la lógica del proceso que ya funciona y se lleva a un controlador vigente, integrándolo por los protocolos que la planta ya usa."},{"pregunta":"¿El programa del PLC y de la HMI queda en manos del cliente?","respuesta":"Sí. Al cierre se entregan los programas, los planos actualizados a lo realmente construido y el manual de operación. No dejamos candados: quien contrató el sistema tiene que poder mantenerlo o hacerlo mantener por quien decida."},{"pregunta":"¿Hacen solo el diseño, o solo el tablero?","respuesta":"Los servicios se pueden contratar por separado. También se puede contratar el alcance completo como proyecto llave en mano, con un solo responsable de la ingeniería, el suministro, el montaje y la puesta en marcha."},{"pregunta":"¿En qué zona prestan el servicio?","respuesta":"La base está en Cali, Valle del Cauca, y desde ahí se atienden proyectos en la región. Para trabajos fuera de la ciudad, escríbanos y lo revisamos según el alcance."}],"image":{"alt":"Interior de un tablero en acero inoxidable con PLC modular, switches de red industrial, protecciones y borneras cableadas","src":"https://bzrjeduxjkwvtdaohjrh.supabase.co/storage/v1/object/public/site-images/cabeceras/interior-tablero-plc-red-900.webp","width":900,"height":437},"intro":"La agrupación en cuatro líneas es una forma de leer el portafolio, no un compartimento: la mayoría de los proyectos toca varias a la vez —un tablero nuevo viene con su diseño eléctrico, y una automatización termina con telemetría.","title":"Nueve servicios, cuatro líneas de trabajo","eyebrow":"Portafolio","subtitle":"Ofrecemos servicios de alta calidad para dar soluciones asertivas, reduciendo el riesgo y dando la seguridad de que nuestra propuesta es la mejor, brindando tranquilidad y respaldo a cada cliente en su proceso de producción."},"noEncontrada":{"body":"El enlace puede estar mal escrito o la página pudo haber cambiado de dirección. Desde aquí puede volver al inicio o ir directo al portafolio de servicios.","title":"Esta página no existe"},"proyectoDetalle":{"cta":{"body":"Escríbanos con los datos de su proceso y revisamos si se puede abordar de la misma forma.","title":"¿Quiere un resultado parecido en su planta?"},"notaServicios":"Este caso combinó varios servicios de PIYC. Abajo puede ver cada uno."},"servicioDetalle":{"ctaTexto":"Escríbanos con los datos del equipo o del proceso y le decimos qué información hace falta para cotizar."}}'::jsonb),
  ('seo', '{"defaultTitle":"PIYC — Automatización e ingeniería eléctrica en Cali","titleTemplate":"%s | PIYC","defaultDescription":"Automatización de procesos con PLC y HMI/SCADA, tableros de control y potencia, telemetría y proyectos eléctricos llave en mano en Cali, Valle del Cauca.","keywords":["automatización industrial Cali","tableros de control Cali","programación PLC","HMI SCADA","ingeniería eléctrica industrial","telemetría industrial","cuartos fríos Cali"],"paginas":{"inicio":{"title":"PIYC — Automatización e ingeniería eléctrica en Cali","description":"Automatización de procesos con PLC y HMI/SCADA, tableros de control y potencia, telemetría y proyectos eléctricos llave en mano en Cali, Valle del Cauca."},"nosotros":{"title":"Quiénes somos","description":"PIYC — Programación Industrial y Control S.A.S.: ingenieros dedicados a proyectos de ingeniería, montaje y mantenimiento de equipos eléctricos y electrónicos."},"servicios":{"title":"Servicios","description":"Automatización con PLC, tableros de control y potencia, ingeniería eléctrica, telemetría, telecontrol, proyectos llave en mano, refrigeración y climatización."},"proyectos":{"title":"Proyectos","description":"Casos de éxito de PIYC: automatizaciones, sistemas de control e ingeniería eléctrica entregados en plantas de producción del Valle del Cauca."},"contacto":{"title":"Contacto","description":"Escríbale a PIYC por WhatsApp o déjenos los datos de su proyecto. Cl. 33 #5-76, Cali, Valle del Cauca. Automatización industrial e ingeniería eléctrica."}}}'::jsonb)
on conflict (key) do update set
  value      = excluded.value,
  updated_at = now();

-- ---------------------------------------------------------------------------
-- Horario de atención dentro de `contact`.
--
-- Confirmado por Cesar contra la ficha de Google del negocio (21-sep-2026):
-- lunes a viernes de 8:00 a. m. a 5:00 p. m.; sábado y domingo cerrado. Los
-- días cerrados no se listan en `schema`: en schema.org, un día que no aparece
-- en `openingHours` es un día cerrado.
--
-- Se FUSIONA (`||`) sobre el JSON existente para no pisar dirección,
-- teléfonos, correos ni —sobre todo— `whatsappFormulario`, que es el destino
-- del formulario de contacto (regla 5 de AGENTS.md). Idempotente: correrlo dos
-- veces deja exactamente lo mismo.
update public.site_settings
   set value = value || jsonb_build_object(
         'horario',
         jsonb_build_object(
           'label',  'Lunes a viernes, 8:00 a. m. – 5:00 p. m. · Sábados y domingos, cerrado',
           'schema', jsonb_build_array('Mo-Fr 08:00-17:00')
         )
       ),
       updated_at = now()
 where key = 'contact';

-- ---------------------------------------------------------------------------
-- Canales públicos de contacto: UN solo número y UN solo correo.
--
-- Decisión de Cesar (21-sep-2026): el celular personal del fundador y su
-- correo dejan de publicarse en el sitio. El número que queda es el de la
-- empresa —el mismo destino del formulario (regla 5 de AGENTS.md)— y el correo
-- visible pasa a fabian.gaviria@piycsas.com. `0001_contenido.sql` §6 sembró la
-- versión anterior; esta fusión la corrige sin tocar dirección ni horario.
--
-- Idempotente: reescribe solo estas cinco claves, siempre con el mismo valor.
update public.site_settings
   set value = value || jsonb_build_object(
         'phones',   jsonb_build_array(
           jsonb_build_object('label', '+57 321 761 7958', 'intl', '573217617958')
         ),
         'whatsapp', jsonb_build_array(
           jsonb_build_object(
             'label', '+57 321 761 7958', 'intl', '573217617958',
             'person', null, 'principal', true
           )
         ),
         'emails',   jsonb_build_array(
           jsonb_build_object('address', 'fabian.gaviria@piycsas.com', 'person', null)
         ),
         'primaryWhatsApp',    '573217617958',
         'whatsappFormulario', '573217617958'
       ),
       updated_at = now()
 where key = 'contact';
